import { test } from 'node:test';
import assert from 'node:assert/strict';
import { proficiencia } from './solution.mjs';

test('fundamentos: dobro do número', async () => {
  assert.equal(await proficiencia({ caso: 'dobro', numero: 5 }), 10);
