test('funções e listas: soma dos itens', async () => {
  assert.equal(await proficiencia({ caso: 'soma', lista: [1, 2, 3] }), 6);
});

test('assincronismo: espera e devolve pronto', async () => {
  const inicio = Date.now();
  const r = await proficiencia({ caso: 'espera', ms: 10 });
  assert.equal(r, 'pronto');
  assert.ok(Date.now() - inicio >= 5, 'deve esperar pelo menos o tempo pedido');
});

