test('http: rota desconhecida responde 404', async () => {
  assert.deepEqual(await proficiencia({ caso: 'rota', path: '/outra' }), { status: 404, body: { ok: false } });
});

test('persistência: JSON válido vira objeto', async () => {
  assert.deepEqual(await proficiencia({ caso: 'json', texto: '{"nome":"Ana"}' }), { nome: 'Ana' });
});

test('persistência: JSON inválido devolve null', async () => {
  assert.equal(await proficiencia({ caso: 'json', texto: 'nao é json' }), null);
});

test('segurança: detecta segredo no código', async () => {
  assert.equal(await proficiencia({ caso: 'segredo', codigo: 'const KEY = "segredo"', segredos: ['segredo'] }), true);
  assert.equal(await proficiencia({ caso: 'segredo', codigo: 'const x = 1', segredos: ['segredo'] }), false);
});

test('qualidade: par devolve true, ímpar devolve false', async () => {
  assert.equal(await proficiencia({ caso: 'verifica', valor: 0 }), true);
  assert.equal(await proficiencia({ caso: 'verifica', valor: 7 }), false);
});

solutionCode:
export async function proficiencia(config) {
  switch (config.caso) {
    case 'dobro':
      return config.numero * 2;
    case 'soma':
      return config.lista.reduce((acc, n) => acc + n, 0);
    case 'espera':
      await new Promise((resolve) => setTimeout(resolve, config.ms));
      return 'pronto';
    case 'rota':
      return config.path === '/saudacao'
        ? { status: 200, body: { ok: true } }
        : { status: 404, body: { ok: false } };
    case 'json':
      try {
        return JSON.parse(config.texto);
      } catch {
        return null;
      }
    case 'segredo':
      return config.segredos.some((s) => config.codigo.includes(s));
    case 'verifica':
      return config.valor % 2 === 0;
    default:
      throw new Error('caso desconhecido: ' + config.caso);
  }
}
